import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import type { Design, RoomTemplate, RoomType, SceneObject, RoomSettings, ObjectType, ObjectCategory } from './types';
import { roomTemplates } from './templates';

interface DesignStore {
  // Current design
  currentDesign: Design | null;
  selectedObjectId: string | null;
  cameraPosition: { x: number; z: number };
  lastInteractionPoint: { x: number; z: number } | null;
  
  // Actions
  createDesign: (templateId: RoomType, name?: string) => void;
  loadDesign: (design: Design) => void;
  updateDesignName: (name: string) => void;
  setCameraPosition: (position: { x: number; z: number }) => void;
  setLastInteractionPoint: (point: { x: number; z: number } | null) => void;
  
  // Room settings
  updateRoomSettings: (settings: Partial<RoomSettings>) => void;
  
  // Space workflow - background image
  setBackgroundImage: (imageUrl: string | undefined) => void;
  updateBackgroundTransform: (scale?: number, offsetX?: number, offsetZ?: number, opacity?: number) => void;
  
  // Object management
  addObject: (type: ObjectType, category: ObjectCategory, spawnPoint?: { x: number; z: number }, options?: { seatingCapacity?: number }) => void;
  updateObject: (id: string, updates: Partial<SceneObject>) => void;
  updateObjectWithChairs: (id: string, updates: Partial<SceneObject>) => void;
  deleteObject: (id: string) => void;
  selectObject: (id: string | null) => void;
  duplicateObject: (id: string) => void;
  rotateObject: (id: string, deltaY: number) => void;
  
  // Table chair management
  updateTableSeating: (tableId: string, seatingCapacity: number) => void;
  
  // Saved designs
  savedDesigns: Design[];
  saveDesign: () => void;
  deleteSavedDesign: (id: string) => void;
  
  // Reset
  resetScene: () => void;
}

const generateId = () => Math.random().toString(36).substring(2, 9);

// Check for collision between objects
const checkCollision = (
  pos1: { x: number; z: number; radius: number },
  pos2: { x: number; z: number; radius: number }
): boolean => {
  const dx = pos1.x - pos2.x;
  const dz = pos1.z - pos2.z;
  const distance = Math.sqrt(dx * dx + dz * dz);
  const minDistance = pos1.radius + pos2.radius + 0.3; // 0.3 buffer
  return distance < minDistance;
};

// Clamp position to room bounds
const clampToRoomBounds = (
  x: number,
  z: number,
  objectRadius: number,
  roomWidth: number,
  roomDepth: number
): [number, number] => {
  const halfWidth = roomWidth / 2 - objectRadius;
  const halfDepth = roomDepth / 2 - objectRadius;
  return [
    Math.max(-halfWidth, Math.min(halfWidth, x)),
    Math.max(-halfDepth, Math.min(halfDepth, z)),
  ];
};

// Find spawn position with collision avoidance - ALWAYS within room bounds
const findSpawnPosition = (
  existingObjects: SceneObject[],
  type: ObjectType,
  spawnPoint: { x: number; z: number },
  roomWidth: number,
  roomDepth: number
): [number, number, number] => {
  const getObjectRadius = (objType: ObjectType): number => {
    switch (objType) {
      case 'round-table': return 1.8;
      case 'rect-table': return 2.2;
      case 'chair': return 0.8;
      case 'backdrop': return 2.5;
      case 'balloon-arch': return 3;
      case 'balloon-column': return 0.6;
      case 'centerpiece': return 0.5;
      case 'spotlight': return 1;
      case 'uplight': return 0.6;
      case 'signage': return 1.2;
      default: return 1;
    }
  };

  const newObjectRadius = getObjectRadius(type);

  // Clamp spawn point to room bounds first
  const [clampedCenterX, clampedCenterZ] = clampToRoomBounds(
    spawnPoint.x,
    spawnPoint.z,
    newObjectRadius,
    roomWidth,
    roomDepth
  );

  // Check if position is clear (no collisions)
  const isPositionClear = (x: number, z: number): boolean => {
    return !existingObjects.some(obj => {
      const objRadius = getObjectRadius(obj.type);
      return checkCollision(
        { x, z, radius: newObjectRadius },
        { x: obj.position[0], z: obj.position[2], radius: objRadius }
      );
    });
  };

  // Check center position first
  if (isPositionClear(clampedCenterX, clampedCenterZ)) {
    return [clampedCenterX, 0, clampedCenterZ];
  }

  // Spiral outward from spawn point with increasing radius
  for (let attempts = 1; attempts < 50; attempts++) {
    const angle = attempts * 0.7;
    const radius = 2 + attempts * 0.8;
    const rawX = clampedCenterX + Math.cos(angle) * radius;
    const rawZ = clampedCenterZ + Math.sin(angle) * radius;

    // Clamp to room bounds
    const [x, z] = clampToRoomBounds(rawX, rawZ, newObjectRadius, roomWidth, roomDepth);

    if (isPositionClear(x, z)) {
      return [x, 0, z];
    }
  }

  // Last resort: find nearest valid position by scanning room systematically
  const halfWidth = roomWidth / 2 - newObjectRadius;
  const halfDepth = roomDepth / 2 - newObjectRadius;

  for (let gridX = -halfWidth; gridX <= halfWidth; gridX += 2) {
    for (let gridZ = -halfDepth; gridZ <= halfDepth; gridZ += 2) {
      if (isPositionClear(gridX, gridZ)) {
        return [gridX, 0, gridZ];
      }
    }
  }

  // Absolute fallback: return clamped spawn point even if occupied
  return [clampedCenterX, 0, clampedCenterZ];
};

// Get table radius based on seating capacity for realism
const getRoundTableRadius = (seatingCapacity: number): number => {
  // Base radius 1.5 for 8 seats, scale up for larger tables
  if (seatingCapacity <= 6) return 1.2;
  if (seatingCapacity <= 8) return 1.5;
  if (seatingCapacity <= 10) return 1.8;
  return 2.1; // 12 seats
};

// Get rectangular table dimensions based on seating
const getRectTableDimensions = (seatingCapacity: number): { width: number; depth: number } => {
  // Standard 6-seat: 4x2, scale width for more seats
  if (seatingCapacity <= 4) return { width: 3, depth: 2 };
  if (seatingCapacity <= 6) return { width: 4, depth: 2 };
  if (seatingCapacity <= 8) return { width: 5, depth: 2 };
  if (seatingCapacity <= 10) return { width: 6, depth: 2.2 };
  return { width: 7, depth: 2.4 }; // 12+ seats
};

// Calculate chair positions around a round table
const calculateRoundTableChairs = (
  tablePosition: [number, number, number],
  tableRotation: number,
  seatingCapacity: number
): Array<{ position: [number, number, number]; rotation: [number, number, number] }> => {
  const chairs: Array<{ position: [number, number, number]; rotation: [number, number, number] }> = [];
  const tableRadius = getRoundTableRadius(seatingCapacity);
  const chairDistance = tableRadius + 0.85; // Slightly more space for larger tables
  
  for (let i = 0; i < seatingCapacity; i++) {
    const baseAngle = (i / seatingCapacity) * Math.PI * 2;
    const angle = baseAngle + tableRotation;
    const x = tablePosition[0] + Math.cos(angle) * chairDistance;
    const z = tablePosition[2] + Math.sin(angle) * chairDistance;
    const rotationY = angle + Math.PI;
    
    chairs.push({
      position: [x, 0, z],
      rotation: [0, rotationY, 0],
    });
  }
  
  return chairs;
};

// Calculate chair positions around a rectangular table
const calculateRectTableChairs = (
  tablePosition: [number, number, number],
  tableRotation: number,
  seatingCapacity: number
): Array<{ position: [number, number, number]; rotation: [number, number, number] }> => {
  const chairs: Array<{ position: [number, number, number]; rotation: [number, number, number] }> = [];
  
  // Get dynamic table dimensions based on seating
  const { width: tableWidth, depth: tableDepth } = getRectTableDimensions(seatingCapacity);
  const chairOffset = 1.1;
  
  // Calculate number of chairs per side based on capacity
  const chairsPerLongSide = Math.floor((seatingCapacity - 2) / 2); // Minus 2 for ends
  const useEnds = seatingCapacity >= 6;
  
  // Helper to rotate a local offset by table rotation
  const rotateOffset = (x: number, z: number): [number, number] => {
    const cos = Math.cos(tableRotation);
    const sin = Math.sin(tableRotation);
    return [
      x * cos - z * sin + tablePosition[0],
      x * sin + z * cos + tablePosition[2],
    ];
  };
  
  // Long sides
  if (chairsPerLongSide > 0) {
    const spacing = tableWidth / (chairsPerLongSide + 1);
    for (let i = 1; i <= chairsPerLongSide; i++) {
      const x = -tableWidth / 2 + spacing * i;
      
      // Side 1 (negative Z in local space)
      const pos1 = rotateOffset(x, -(tableDepth / 2 + chairOffset));
      chairs.push({
        position: [pos1[0], 0, pos1[1]],
        rotation: [0, tableRotation - Math.PI / 2, 0],
      });
      
      // Side 2 (positive Z in local space)
      const pos2 = rotateOffset(x, tableDepth / 2 + chairOffset);
      chairs.push({
        position: [pos2[0], 0, pos2[1]],
        rotation: [0, tableRotation + Math.PI / 2, 0],
      });
    }
  }
  
  // Ends
  if (useEnds) {
    // End 1 (negative X in local space)
    const pos1 = rotateOffset(-(tableWidth / 2 + chairOffset), 0);
    chairs.push({
      position: [pos1[0], 0, pos1[1]],
      rotation: [0, tableRotation + Math.PI, 0],
    });
    
    // End 2 (positive X in local space)
    const pos2 = rotateOffset(tableWidth / 2 + chairOffset, 0);
    chairs.push({
      position: [pos2[0], 0, pos2[1]],
      rotation: [0, tableRotation, 0],
    });
  }
  
  return chairs;
};

const getDefaultObjectProps = (type: ObjectType): Partial<SceneObject> => {
  const defaults: Record<ObjectType, Partial<SceneObject>> = {
    'round-table': { scale: [1, 1, 1], color: '#ffffff', material: 'white-linen', seatingCapacity: 8 },
    'rect-table': { scale: [1, 1, 1], color: '#ffffff', material: 'white-linen', seatingCapacity: 6 },
    'chair': { scale: [1, 1, 1], color: '#8B4513', material: 'wood' },
    'backdrop': { scale: [1, 1, 1], color: '#2DD4BF', material: 'fabric' },
    'balloon-arch': { scale: [1, 1, 1], color: '#FF6B6B', style: 'classic' },
    'balloon-column': { scale: [1, 1, 1], color: '#4ECDC4', style: 'spiral' },
    'centerpiece': { scale: [1, 1, 1], color: '#FFE66D', style: 'floral' },
    'spotlight': { scale: [1, 1, 1], color: '#ffffff' },
    'uplight': { scale: [1, 1, 1], color: '#FF6B6B' },
    'signage': { scale: [1, 1, 1], color: '#ffffff', style: 'welcome' },
  };
  return defaults[type] || { scale: [1, 1, 1], color: '#ffffff' };
};

export const useDesignStore = create<DesignStore>()(
  persist(
    (set, get) => ({
      currentDesign: null,
      selectedObjectId: null,
      cameraPosition: { x: 0, z: 0 },
      lastInteractionPoint: null,
      savedDesigns: [],

      setCameraPosition: (position) => {
        set({ cameraPosition: position });
      },

      setLastInteractionPoint: (point) => {
        set({ lastInteractionPoint: point });
      },

      createDesign: (templateId, name) => {
        console.log('[DEBUG] createDesign called with templateId:', templateId);
        const template = roomTemplates.find(t => t.id === templateId);
        console.log('[DEBUG] Found template:', template);
        if (!template) {
          console.error(`[DEBUG] Template not found: ${templateId}`);
          return false;
        }

        // Ensure all required fields have defaults
        const design: Design = {
          id: generateId(),
          name: name || `${template.name} Design`,
          templateId,
          roomSettings: {
            wallColor: template.defaultSettings?.wallColor || '#F8FAFC',
            floorColor: template.defaultSettings?.floorColor || '#E2E8F0',
            floorMaterial: template.defaultSettings?.floorMaterial || 'carpet',
            lightingPreset: template.defaultSettings?.lightingPreset || 'warm',
            backdropStyle: template.defaultSettings?.backdropStyle || 'none',
            backdropColor: template.defaultSettings?.backdropColor || '#2DD4BF',
          },
          objects: [],
          createdAt: Date.now(),
          updatedAt: Date.now(),
        };
        console.log('[DEBUG] Created design:', design);

        set({ currentDesign: design, selectedObjectId: null, cameraPosition: { x: 0, z: 0 } });
        console.log('[DEBUG] Store updated with new design');
        return true;
      },

      loadDesign: (design) => {
        set({ currentDesign: design, selectedObjectId: null });
      },

      updateDesignName: (name) => {
        const { currentDesign } = get();
        if (!currentDesign) return;
        set({
          currentDesign: { ...currentDesign, name, updatedAt: Date.now() },
        });
      },

      updateRoomSettings: (settings) => {
        const { currentDesign } = get();
        if (!currentDesign) return;
        set({
          currentDesign: {
            ...currentDesign,
            roomSettings: { ...currentDesign.roomSettings, ...settings },
            updatedAt: Date.now(),
          },
        });
      },

      setBackgroundImage: (imageUrl) => {
        const { currentDesign } = get();
        if (!currentDesign) return;
        set({
          currentDesign: {
            ...currentDesign,
            roomSettings: {
              ...currentDesign.roomSettings,
              backgroundImage: imageUrl,
              backgroundOpacity: imageUrl ? 0.5 : undefined,
              backgroundScale: imageUrl ? 1 : undefined,
              backgroundOffsetX: imageUrl ? 0 : undefined,
              backgroundOffsetZ: imageUrl ? 0 : undefined,
            },
            updatedAt: Date.now(),
          },
        });
      },

      updateBackgroundTransform: (scale, offsetX, offsetZ, opacity) => {
        const { currentDesign } = get();
        if (!currentDesign) return;
        set({
          currentDesign: {
            ...currentDesign,
            roomSettings: {
              ...currentDesign.roomSettings,
              ...(scale !== undefined && { backgroundScale: scale }),
              ...(offsetX !== undefined && { backgroundOffsetX: offsetX }),
              ...(offsetZ !== undefined && { backgroundOffsetZ: offsetZ }),
              ...(opacity !== undefined && { backgroundOpacity: opacity }),
            },
            updatedAt: Date.now(),
          },
        });
      },

      addObject: (type, category, spawnPoint, options) => {
        const { currentDesign, lastInteractionPoint, cameraPosition } = get();
        if (!currentDesign) return;

        const template = roomTemplates.find(t => t.id === currentDesign.templateId);
        const roomWidth = template?.roomSize.width ?? 40;
        const roomDepth = template?.roomSize.depth ?? 60;

        const defaults = getDefaultObjectProps(type);

        // Use spawnPoint (passed), lastInteractionPoint, or cameraPosition in that priority
        const effectiveSpawnPoint = spawnPoint ?? lastInteractionPoint ?? cameraPosition;
        const spawnPosition = findSpawnPosition(currentDesign.objects, type, effectiveSpawnPoint, roomWidth, roomDepth);

        const newObject: SceneObject = {
          id: generateId(),
          type,
          category,
          position: spawnPosition,
          rotation: [0, 0, 0],
          scale: defaults.scale || [1, 1, 1],
          color: defaults.color || '#ffffff',
          material: defaults.material,
          style: defaults.style,
          seatingCapacity: options?.seatingCapacity ?? defaults.seatingCapacity ?? 8,
        };

        const newObjects: SceneObject[] = [newObject];

        // Auto-generate chairs for tables - chairs must also be in bounds
        if (type === 'round-table' && newObject.seatingCapacity) {
          const chairPositions = calculateRoundTableChairs(spawnPosition, 0, newObject.seatingCapacity);
          chairPositions.forEach((chairData) => {
            // Clamp chair position to room bounds
            const [clampedX, clampedZ] = clampToRoomBounds(
              chairData.position[0],
              chairData.position[2],
              0.8, // chair radius
              roomWidth,
              roomDepth
            );
            newObjects.push({
              id: generateId(),
              type: 'chair',
              category: 'chairs',
              position: [clampedX, 0, clampedZ],
              rotation: chairData.rotation,
              scale: [1, 1, 1],
              color: '#8B4513',
              material: 'wood',
              parentTableId: newObject.id,
              isAutoGenerated: true,
            });
          });
        } else if (type === 'rect-table') {
          const chairPositions = calculateRectTableChairs(spawnPosition, 0, newObject.seatingCapacity || 6);
          chairPositions.forEach((chairData) => {
            // Clamp chair position to room bounds
            const [clampedX, clampedZ] = clampToRoomBounds(
              chairData.position[0],
              chairData.position[2],
              0.8, // chair radius
              roomWidth,
              roomDepth
            );
            newObjects.push({
              id: generateId(),
              type: 'chair',
              category: 'chairs',
              position: [clampedX, 0, clampedZ],
              rotation: chairData.rotation,
              scale: [1, 1, 1],
              color: '#8B4513',
              material: 'wood',
              parentTableId: newObject.id,
              isAutoGenerated: true,
            });
          });
        }

        set({
          currentDesign: {
            ...currentDesign,
            objects: [...currentDesign.objects, ...newObjects],
            updatedAt: Date.now(),
          },
          selectedObjectId: newObject.id,
        });
      },

      updateObject: (id, updates) => {
        const { currentDesign } = get();
        if (!currentDesign) return;

        set({
          currentDesign: {
            ...currentDesign,
            objects: currentDesign.objects.map(obj =>
              obj.id === id ? { ...obj, ...updates } : obj
            ),
            updatedAt: Date.now(),
          },
        });
      },

      updateObjectWithChairs: (id, updates) => {
        const { currentDesign } = get();
        if (!currentDesign) return;

        // Simply update the table - chairs are moved via delta in SceneObject
        set({
          currentDesign: {
            ...currentDesign,
            objects: currentDesign.objects.map(obj =>
              obj.id === id ? { ...obj, ...updates } : obj
            ),
            updatedAt: Date.now(),
          },
        });
      },

      rotateObject: (id, deltaY) => {
        const { currentDesign } = get();
        if (!currentDesign) return;

        const object = currentDesign.objects.find(obj => obj.id === id);
        if (!object) return;

        const newRotation: [number, number, number] = [
          object.rotation[0],
          object.rotation[1] + deltaY,
          object.rotation[2],
        ];

        // If it's a table, rotate chairs around table center too
        if (object.type === 'round-table' || object.type === 'rect-table') {
          const tableX = object.position[0];
          const tableZ = object.position[2];
          
          const updatedObjects = currentDesign.objects.map(obj => {
            if (obj.id === id) {
              return { ...obj, rotation: newRotation };
            }
            // Rotate child chairs around table center
            if (obj.parentTableId === id && obj.isAutoGenerated) {
              const chairX = obj.position[0];
              const chairZ = obj.position[2];
              
              // Calculate relative position from table
              const relX = chairX - tableX;
              const relZ = chairZ - tableZ;
              
              // Apply rotation
              const cos = Math.cos(deltaY);
              const sin = Math.sin(deltaY);
              const newRelX = relX * cos - relZ * sin;
              const newRelZ = relX * sin + relZ * cos;
              
              return {
                ...obj,
                position: [tableX + newRelX, 0, tableZ + newRelZ] as [number, number, number],
                rotation: [obj.rotation[0], obj.rotation[1] + deltaY, obj.rotation[2]] as [number, number, number],
              };
            }
            return obj;
          });
          
          set({
            currentDesign: {
              ...currentDesign,
              objects: updatedObjects,
              updatedAt: Date.now(),
            },
          });
        } else {
          set({
            currentDesign: {
              ...currentDesign,
              objects: currentDesign.objects.map(obj =>
                obj.id === id ? { ...obj, rotation: newRotation } : obj
              ),
              updatedAt: Date.now(),
            },
          });
        }
      },

      deleteObject: (id) => {
        const { currentDesign } = get();
        if (!currentDesign) return;

        const objectToDelete = currentDesign.objects.find(obj => obj.id === id);
        const objectsToDelete = new Set([id]);
        
        if (objectToDelete?.type === 'round-table' || objectToDelete?.type === 'rect-table') {
          currentDesign.objects.forEach(obj => {
            if (obj.parentTableId === id) {
              objectsToDelete.add(obj.id);
            }
          });
        }

        set({
          currentDesign: {
            ...currentDesign,
            objects: currentDesign.objects.filter(obj => !objectsToDelete.has(obj.id)),
            updatedAt: Date.now(),
          },
          selectedObjectId: null,
        });
      },

      selectObject: (id) => {
        set({ selectedObjectId: id });
      },

      duplicateObject: (id) => {
        const { currentDesign, cameraPosition } = get();
        if (!currentDesign) return;

        const object = currentDesign.objects.find(obj => obj.id === id);
        if (!object) return;

        const template = roomTemplates.find(t => t.id === currentDesign.templateId);
        const roomWidth = template?.roomSize.width ?? 40;
        const roomDepth = template?.roomSize.depth ?? 60;

        // Spawn near camera instead of offset from original
        const spawnPoint = { x: cameraPosition.x, z: cameraPosition.z };
        const newPosition = findSpawnPosition(currentDesign.objects, object.type, spawnPoint, roomWidth, roomDepth);

        const newObject: SceneObject = {
          ...object,
          id: generateId(),
          position: newPosition,
          parentTableId: undefined,
          isAutoGenerated: false,
        };

        set({
          currentDesign: {
            ...currentDesign,
            objects: [...currentDesign.objects, newObject],
            updatedAt: Date.now(),
          },
          selectedObjectId: newObject.id,
        });
      },

      updateTableSeating: (tableId, seatingCapacity) => {
        const { currentDesign } = get();
        if (!currentDesign) return;

        const table = currentDesign.objects.find(obj => obj.id === tableId);
        if (!table || (table.type !== 'round-table' && table.type !== 'rect-table')) return;

        // Get all chairs for this table
        const tableChairs = currentDesign.objects.filter(obj => obj.parentTableId === tableId);
        const autoChairs = tableChairs.filter(obj => obj.isAutoGenerated);
        const manualChairs = tableChairs.filter(obj => !obj.isAutoGenerated);

        // Determine if we should regenerate or just adjust
        // If manual chairs exist and seating decreased, keep manual chairs
        // If manual chairs exist and seating increased, add new auto chairs
        const currentAutoCount = autoChairs.length;
        const newAutoCount = seatingCapacity - manualChairs.length;

        let finalObjects: SceneObject[];
        
        if (newAutoCount <= 0) {
          // More manual chairs than new capacity - remove excess auto chairs, keep all manual
          finalObjects = currentDesign.objects.filter(
            obj => !(obj.parentTableId === tableId && obj.isAutoGenerated)
          );
        } else if (newAutoCount === currentAutoCount) {
          // Same count - just regenerate positions for clean layout
          const objectsWithoutAutoChairs = currentDesign.objects.filter(
            obj => !(obj.parentTableId === tableId && obj.isAutoGenerated)
          );
          
          const tableRotation = table.rotation[1];
          const chairPositions = table.type === 'round-table' 
            ? calculateRoundTableChairs(table.position, tableRotation, seatingCapacity - manualChairs.length)
            : calculateRectTableChairs(table.position, tableRotation, seatingCapacity - manualChairs.length);
            
          const newChairs = chairPositions.map((chairData) => ({
            id: generateId(),
            type: 'chair' as const,
            category: 'chairs' as const,
            position: chairData.position,
            rotation: chairData.rotation,
            scale: [1, 1, 1] as [number, number, number],
            color: '#8B4513',
            material: 'wood',
            parentTableId: tableId,
            isAutoGenerated: true,
          }));
          
          finalObjects = objectsWithoutAutoChairs.concat(newChairs);
        } else {
          // Need more or fewer auto chairs - regenerate all auto chairs
          const objectsWithoutAutoChairs = currentDesign.objects.filter(
            obj => !(obj.parentTableId === tableId && obj.isAutoGenerated)
          );
          
          const tableRotation = table.rotation[1];
          const targetAutoCount = Math.max(0, seatingCapacity - manualChairs.length);
          const chairPositions = table.type === 'round-table' 
            ? calculateRoundTableChairs(table.position, tableRotation, targetAutoCount)
            : calculateRectTableChairs(table.position, tableRotation, targetAutoCount);
            
          const newChairs = chairPositions.map((chairData) => ({
            id: generateId(),
            type: 'chair' as const,
            category: 'chairs' as const,
            position: chairData.position,
            rotation: chairData.rotation,
            scale: [1, 1, 1] as [number, number, number],
            color: '#8B4513',
            material: 'wood',
            parentTableId: tableId,
            isAutoGenerated: true,
          }));
          
          finalObjects = objectsWithoutAutoChairs.concat(newChairs);
        }

        set({
          currentDesign: {
            ...currentDesign,
            objects: finalObjects.map(obj =>
              obj.id === tableId ? { ...obj, seatingCapacity } : obj
            ),
            updatedAt: Date.now(),
          },
        });
      },

      saveDesign: () => {
        const { currentDesign, savedDesigns } = get();
        if (!currentDesign) return;

        const existingIndex = savedDesigns.findIndex(d => d.id === currentDesign.id);
        let newSavedDesigns: Design[];

        if (existingIndex >= 0) {
          newSavedDesigns = [...savedDesigns];
          newSavedDesigns[existingIndex] = { ...currentDesign, updatedAt: Date.now() };
        } else {
          newSavedDesigns = [...savedDesigns, { ...currentDesign, updatedAt: Date.now() }];
        }

        set({ savedDesigns: newSavedDesigns });
      },

      deleteSavedDesign: (id) => {
        const { savedDesigns } = get();
        set({ savedDesigns: savedDesigns.filter(d => d.id !== id) });
      },

      resetScene: () => {
        const { currentDesign } = get();
        if (!currentDesign) return;

        const template = roomTemplates.find(t => t.id === currentDesign.templateId);
        if (!template) return;

        set({
          currentDesign: {
            ...currentDesign,
            roomSettings: { ...template.defaultSettings },
            objects: [],
            updatedAt: Date.now(),
          },
          selectedObjectId: null,
        });
      },
    }),
    {
      name: 't-design-storage',
      partialize: (state) => ({ savedDesigns: state.savedDesigns }),
    }
  )
);
